extends Node

func _ready():
	var args = OS.get_cmdline_args()
	var dash_idx = -1
	for i in range(args.size()):
		if args[i] == "--":
			dash_idx = i
			break
	if dash_idx == -1:
		return
	var custom = args.slice(dash_idx + 1)
	var port = 0
	var clients = 0
	var frames = 0
	var score_deltas = []
	var out_path = ""

	for i in range(custom.size()):
		var a = custom[i]
		if a.begins_with("--port="): port = a.split("=")[1].to_int()
		elif a.begins_with("--clients="): clients = a.split("=")[1].to_int()
		elif a.begins_with("--frames="): frames = a.split("=")[1].to_int()
		elif a.begins_with("--score-deltas="): score_deltas = a.split("=")[1].split(",").map(func(s): return s.to_int())
		elif a.begins_with("--out="): out_path = a.split("=")[1]

	run(port, clients, frames, score_deltas, out_path)

var peer_nodes = {}
var multiplayer_apis = {}

func run(port, n_clients, frames, deltas, out):
	var server_api = SceneMultiplayer.new()
	get_tree().set_multiplayer(server_api, "/root/Main")
	var server_peer = ENetMultiplayerPeer.new()
	server_peer.create_server(port, n_clients)
	server_api.multiplayer_peer = server_peer
	multiplayer_apis[1] = server_api

	var client_peers = []
	for i in range(n_clients):
		var api = SceneMultiplayer.new()
		var client_peer = ENetMultiplayerPeer.new()
		client_peer.create_client("127.0.0.1", port)
		api.multiplayer_peer = client_peer
		multiplayer_apis[client_peer.get_unique_id()] = api
		client_peers.append(client_peer)

	server_api.peer_connected.connect(func(id):
		var p = preload("res://player.tscn").instantiate()
		p.name = str(id)
		get_node("Players").add_child(p)
		server_api.set_multiplayer_authority(p, id)
	)

	# spawn host's own player
	var host_p = preload("res://player.tscn").instantiate()
	host_p.name = str(1)
	get_node("Players").add_child(host_p)
	server_api.set_multiplayer_authority(host_p, 1)

	# client logic once they connected
	for i in range(frames):
		await get_tree().process_frame

	# run client score updates now that all peers have spawned and synchronized
	for i in range(client_peers.size()):
		var cp = client_peers[i]
		var delta = deltas[i]
		var api = multiplayer_apis[cp.get_unique_id()]
		var p = api.root_node.get_node("Players/%d" % cp.get_unique_id())
		p.rpc("update_score", delta)

	for i in range(5):
		await get_tree().process_frame

	var out_dict = gather_state()
	var f = FileAccess.open(out, FileAccess.WRITE)
	f.store_string(JSON.stringify(out_dict, "\t"))
	f.close()
	get_tree().quit()

func gather_state():
	var all_ids = multiplayer_apis.keys()
	all_ids.sort()
	var clients_out = []
	for api_id in all_ids:
		if api_id == 1: continue
		var peers = []
		for id in all_ids: peers.append(id)
		var players = {}
		var api = multiplayer_apis[api_id]
		var nodes = api.root_node.get_node("Players").get_children()
		for p in nodes:
			var pid = p.name.to_int()
			players[str(pid)] = {
				authority = api.get_multiplayer_authority(p),
				position = [p.position.x, p.position.y],
				score = p.score
			}
		clients_out.append({unique_id = api_id, peers = peers, players = players})

	var server_peers = []
	for id in all_ids: if id != 1: server_peers.append(id)
	var server_players = {}
	var s_nodes = multiplayer_apis[1].root_node.get_node("Players").get_children()
	for p in s_nodes:
		var pid = p.name.to_int()
		server_players[str(pid)] = {
			authority = multiplayer_apis[1].get_multiplayer_authority(p),
			position = [p.position.x, p.position.y],
			score = p.score
		}

	return {
		server = {unique_id = 1, peers = server_peers, players = server_players},
		clients = clients_out
	}

